//! Parity tests against the reference oracle fixture site.
//!
//! `tests/fixtures/expected` was generated by the original generator for
//! the posts in `tests/fixtures/site`; see `tests/fixtures/README.md`. These
//! tests build the fixture site with blogen and compare article bodies, the
//! index, RSS and profile output.

use std::path::{Path, PathBuf};

use blogen::config::LoadedConfig;
use blogen::site;
use regex::Regex;
use tempfile::TempDir;

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn copy_tree(source: &Path, destination: &Path) {
    std::fs::create_dir_all(destination).unwrap();
    for entry in walkdir::WalkDir::new(source).sort_by_file_name() {
        let entry = entry.unwrap();
        let relative = entry.path().strip_prefix(source).unwrap();
        let target = destination.join(relative);
        if entry.file_type().is_dir() {
            std::fs::create_dir_all(&target).unwrap();
        } else {
            std::fs::copy(entry.path(), &target).unwrap();
        }
    }
}

/// Build the fixture site in a temporary directory and return it.
fn build_fixture() -> (TempDir, PathBuf) {
    let fixtures = fixtures_dir();
    let temp = tempfile::tempdir().unwrap();
    let site_dir = temp.path().join("site");
    copy_tree(&fixtures.join("site"), &site_dir);
    let loaded = LoadedConfig::from_file(site_dir.join("blogen.toml")).unwrap();
    let report = site::build(&loaded).expect("build fixture site");
    assert_eq!(report.visible_articles, 8);
    assert_eq!(report.hidden_articles, 1);
    (temp, site_dir)
}

/// Extract the inner HTML of `<div class="markdown">` from a generated page.
fn extract_markdown_body(page: &str) -> Option<String> {
    const OPEN: &str = "<div class=\"markdown\">";
    let start = page.find(OPEN)? + OPEN.len();
    let rest = &page[start..];
    let mut depth = 1_usize;
    let mut index = 0_usize;
    while index < rest.len() {
        let next_open = rest[index..].find("<div").map(|offset| index + offset);
        let next_close = rest[index..].find("</div>").map(|offset| index + offset);
        match (next_open, next_close) {
            (Some(open), Some(close)) if open < close => {
                depth += 1;
                index = open + 4;
            }
            (_, Some(close)) => {
                depth -= 1;
                if depth == 0 {
                    return Some(rest[..close].to_string());
                }
                index = close + 6;
            }
            _ => return None,
        }
    }
    None
}

/// Normalize Mermaid figures to the placeholder used by the oracle.
fn normalize_mermaid(html: &str) -> String {
    let regex = Regex::new(r#"(?s)<figure class="mermaid"[^>]*>.*?</figure>"#).unwrap();
    regex
        .replace_all(html, "<figure class=\"mermaid\"></figure>")
        .to_string()
}

/// Remove whitespace between tags (HTML that differs only in template
/// indentation).
fn normalize_between_tags(html: &str) -> String {
    let regex = Regex::new(r">\s+<").unwrap();
    regex.replace_all(html.trim(), "><").to_string()
}

/// MD5 digest of a Mermaid diagram source (matches `mermaid_static`).
fn md5_hex(bytes: &[u8]) -> String {
    use md5::Digest;
    use std::fmt::Write as _;
    let digest = md5::Md5::digest(bytes);
    let mut out = String::with_capacity(digest.len() * 2);
    for byte in digest {
        let _ = write!(out, "{byte:02x}");
    }
    out
}

fn extract_mermaid_digests(page: &str) -> Vec<String> {
    let regex = Regex::new(r#"data-mermaid-digest="([0-9a-f]+)""#).unwrap();
    regex
        .captures_iter(page)
        .map(|captures| captures[1].to_string())
        .collect()
}

fn expected_mermaid_sources(relative: &Path) -> Vec<String> {
    let path = fixtures_dir()
        .join("expected/mermaid")
        .join(relative)
        .with_extension("html.json");
    if !path.is_file() {
        return Vec::new();
    }
    let source = std::fs::read_to_string(path).unwrap();
    serde_json::from_str(&source).unwrap()
}

#[test]
fn fixture_article_bodies_match_oracle() {
    let (_temp, site_dir) = build_fixture();
    let output = site_dir.join("public");
    let bodies_root = fixtures_dir().join("expected/bodies");

    let mut checked = 0;
    for entry in walkdir::WalkDir::new(&bodies_root).sort_by_file_name() {
        let entry = entry.unwrap();
        if !entry.file_type().is_file() {
            continue;
        }
        let relative = entry.path().strip_prefix(&bodies_root).unwrap();
        let page_path = output.join(relative);
        let page = std::fs::read_to_string(&page_path)
            .unwrap_or_else(|_| panic!("missing generated page {}", page_path.display()));
        let actual = normalize_mermaid(&extract_markdown_body(&page).expect("markdown body"));
        let expected = normalize_mermaid(&std::fs::read_to_string(entry.path()).unwrap());
        assert_eq!(
            actual.trim(),
            expected.trim(),
            "article body differs for {}",
            relative.display()
        );

        // Mermaid diagrams must be rendered statically: each static figure
        // carries the MD5 of its diagram source (the oracle records the raw
        // definitions).
        let expected_digests: Vec<String> = expected_mermaid_sources(relative)
            .into_iter()
            .map(|source| md5_hex(source.trim().as_bytes()))
            .collect();
        assert_eq!(
            extract_mermaid_digests(&page),
            expected_digests,
            "mermaid definitions differ for {}",
            relative.display()
        );
        checked += 1;
    }
    assert_eq!(checked, 9, "expected nine fixture articles");
}

#[test]
fn fixture_index_json_matches_oracle() {
    let (_temp, site_dir) = build_fixture();
    let expected: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(fixtures_dir().join("expected/index.json")).unwrap(),
    )
    .unwrap();
    let actual: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(site_dir.join("public/index.json")).unwrap())
            .unwrap();
    assert_eq!(actual, expected);
}

#[test]
fn fixture_rss_matches_oracle() {
    let (_temp, site_dir) = build_fixture();
    let last_build = Regex::new(r"(?s)<lastBuildDate>.*?</lastBuildDate>").unwrap();
    let expected = last_build
        .replace(
            &std::fs::read_to_string(fixtures_dir().join("expected/rss.xml")).unwrap(),
            "<lastBuildDate/>",
        )
        .to_string();
    let actual = last_build
        .replace(
            &std::fs::read_to_string(site_dir.join("public/rss.xml")).unwrap(),
            "<lastBuildDate/>",
        )
        .to_string();
    assert_eq!(actual, expected);
}

#[test]
fn fixture_index_cards_match_oracle() {
    let (_temp, site_dir) = build_fixture();
    let index = std::fs::read_to_string(site_dir.join("public/index.html")).unwrap();
    let actual = extract_markdown_body(&index).expect("index body");
    let expected = std::fs::read_to_string(fixtures_dir().join("expected/cards.html")).unwrap();
    assert_eq!(
        normalize_between_tags(&actual),
        normalize_between_tags(&expected)
    );
}

#[test]
fn fixture_profile_matches_oracle() {
    let (_temp, site_dir) = build_fixture();
    let actual = std::fs::read_to_string(site_dir.join("profile/README.md")).unwrap();
    let expected =
        std::fs::read_to_string(fixtures_dir().join("expected/profile/README.md")).unwrap();
    assert_eq!(actual.trim_end(), expected.trim_end());
}

#[test]
fn fixture_full_pages_contain_same_bodies() {
    let (_temp, site_dir) = build_fixture();
    let pages_root = fixtures_dir().join("expected/pages");
    let output = site_dir.join("public");
    for entry in walkdir::WalkDir::new(&pages_root).sort_by_file_name() {
        let entry = entry.unwrap();
        if !entry.file_type().is_file() || entry.path().ends_with("index.html") {
            continue;
        }
        let relative = entry.path().strip_prefix(&pages_root).unwrap();
        let page = std::fs::read_to_string(output.join(relative)).unwrap();
        let expected_page = std::fs::read_to_string(entry.path()).unwrap();
        let actual_body = normalize_mermaid(&extract_markdown_body(&page).unwrap());
        let expected_body = normalize_mermaid(&extract_markdown_body(&expected_page).unwrap());
        assert_eq!(
            actual_body.trim(),
            expected_body.trim(),
            "full page body differs for {}",
            relative.display()
        );
    }
}

#[test]
fn fixture_misc_invariants() {
    let (_temp, site_dir) = build_fixture();
    let output = site_dir.join("public");

    // Hidden article exists as .htm, without comments, and is unlisted.
    let hidden = std::fs::read_to_string(output.join("secret/hidden_note.htm")).unwrap();
    assert!(hidden.contains("<title>Hidden Note | Fixture Blog</title>"));
    assert!(!hidden.contains("giscus.app"));
    let index_json = std::fs::read_to_string(output.join("index.json")).unwrap();
    assert!(!index_json.contains("hidden_note"));
    let rss = std::fs::read_to_string(output.join("rss.xml")).unwrap();
    assert!(!rss.contains("hidden_note"));
    let profile = std::fs::read_to_string(site_dir.join("profile/README.md")).unwrap();
    assert!(!profile.contains("hidden_note"));

    // Post images are copied so `../images/photo.png` resolves.
    assert!(output.join("images/photo.png").is_file());

    // Comments are enabled on visible pages.
    let visible = std::fs::read_to_string(output.join("rust/first_post.html")).unwrap();
    assert!(visible.contains("https://giscus.app/client.js"));

    // Theme assets land in the configured directory.
    assert!(output.join("dist/main.css").is_file());
    assert!(output.join("dist/katex.min.css").is_file());
}
